21		"github.com/Bob-xisuke/orb-registry-catalog/internal/input"
22		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
23	)
24	
25	// captureStore is a service.Store that records the exact business inputs
26	// the service dispatches: Register arrives as a service.Record (pushed_at
27	// aside, its six fields are the RegisterInput), and each read method lets
28	// the dispatched service.Query be reconstructed (kind + repository +
29	// selector). It keeps the same duplicate/conflict semantics as the SQLite
30	// adapter so retry and conflict rows behave.
31	type captureStore struct {
32		records    []service.Record
33		byID       map[string]int
34		tags       map[string]map[string]string
35		lastRecord service.Record
36		lastQuery  service.Query
37		fault      error
38		regCalls   int
39		readCalls  int
40	}
41	
42	func newCaptureStore() *captureStore {
43		return &captureStore{
44			byID: make(map[string]int),
45			tags: make(map[string]map[string]string),
46		}
47	}
48	
49	func captureID(repository, digest string) string { return repository + "\x00" + digest }
50	
51	func (s *captureStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
52		s.regCalls++
53		s.lastRecord = in
54		if s.fault != nil {
55			return service.Record{}, 0, s.fault
56		}
57		key := captureID(in.Repository, in.Digest)
58		if idx, ok := s.byID[key]; ok {
59			existing := s.records[idx]
60			if existing.Tag == in.Tag && existing.SignatureVerified == in.SignatureVerified &&
61				existing.RetentionDays == in.RetentionDays && existing.SizeBytes == in.SizeBytes {
62				return existing, service.StatusDuplicate, nil
63			}
64			return service.Record{}, service.StatusConflict, nil
65		}
66		s.byID[key] = len(s.records)
67		s.records = append(s.records, in)
68		if s.tags[in.Repository] == nil {
69			s.tags[in.Repository] = make(map[string]string)
70		}
71		s.tags[in.Repository][in.Tag] = in.Digest
72		return in, service.StatusCreated, nil
73	}
74	
75	func (s *captureStore) ListRecords(repository string) ([]service.Record, error) {
76		s.readCalls++
77		s.lastQuery = service.Query{Kind: service.QueryByRepository, Repository: repository}
78		if s.fault != nil {
79			return nil, s.fault
80		}
81		var out []service.Record
82		for _, record := range s.records {
83			if record.Repository == repository {
84				out = append(out, record)
85			}
86		}
87		return out, nil
88	}
89	
90	func (s *captureStore) RecordByDigest(repository, digest string) (service.Record, error) {
91		s.readCalls++
92		s.lastQuery = service.Query{Kind: service.QueryByDigest, Repository: repository, Digest: digest}
93		if s.fault != nil {
94			return service.Record{}, s.fault
95		}
96		if idx, ok := s.byID[captureID(repository, digest)]; ok {
97			return s.records[idx], nil
98		}
99		return service.Record{}, service.ErrRecordNotFound
100	}
101	
102	func (s *captureStore) RecordByTag(repository, tag string) (service.Record, error) {
103		s.readCalls++
104		s.lastQuery = service.Query{Kind: service.QueryByTag, Repository: repository, Tag: tag}
105		if s.fault != nil {
106			return service.Record{}, s.fault
107		}
108		digest, ok := s.tags[repository][tag]
109		if !ok {
110			return service.Record{}, service.ErrRecordNotFound
111		}
112		return s.records[s.byID[captureID(repository, digest)]], nil
113	}
114	
115	// recordMatchesInput compares the six caller-owned fields; pushed_at is
116	// service-generated and never part of the parsed input.
117	func recordMatchesInput(t *testing.T, r service.Record, in service.RegisterInput) {
118		t.Helper()
119		got := service.RegisterInput{
120			Repository:        r.Repository,
121			Digest:            r.Digest,
122			Tag:               r.Tag,
123			SignatureVerified: r.SignatureVerified,
124			RetentionDays:     r.RetentionDays,
125			SizeBytes:         r.SizeBytes,
126		}
127		if got != in {
128			t.Fatalf("store received %+v, want direct ParseRegistration result %+v", got, in)
129		}
130		if r.PushedAt == "" {
131			t.Fatalf("service generated no pushed_at; the input entry must not")
132		}
133	}
134	
135	func newCaptureRouter(st *captureStore) *gin.Engine {
136		return NewRouterWithStore(st, nil)
137	}
138	
139	// TestDirectAndHTTPRegistrationShareOneEntry drives every registration
140	// shape through both entries and pins their identity: the HTTP handler
141	// passes the direct ParseRegistration result to the service, rejections are
142	// the shared sentinel on one side and the published 400 on the other, and a
143	// rejected body never reaches storage.
144	func TestDirectAndHTTPRegistrationShareOneEntry(t *testing.T) {
145		valid := map[string]string{
146			"plain":             registration("registry-demo/cap", testDigestA, "release", true, regRetention, regSizeA),
147			"trimmed and zeros": `{"repository":"  registry-demo/cap  ","digest":"` + testDigestB + `","tag":"  zero  ","signature_verified":false,"retention_days":1,"size_bytes":0,"extra":"ignored"}`,
148			"exact 2^53+1":      registration("registry-demo/cap", testDigestC, "big", true, 1, 9007199254740993),
149			"exact max int64":   registration("registry-demo/cap", testDigestD, "max", true, 3650, 9223372036854775807),
150			"duplicate keys": `{"repository":"registry-demo/decoy","repository":"registry-demo/cap",` +
151				`"digest":"` + testDigestB + `","digest":"` + testDigestA + `",` +
152				`"tag":"decoy","tag":"release","signature_verified":"x","signature_verified":true,` +
153				`"retention_days":null,"retention_days":30,"size_bytes":"1","size_bytes":1024}`,
154			"unicode escaped keys": `{` +
155				`"\u0072epository":"registry-demo/cap",` +
156				`"\u0064igest":"` + testDigestE + `",` +
157				`"\u0074ag":"escaped",` +
158				`"signature_\u0076erified":true,` +
159				`"retention_\u0064ays":30,` +
160				`"size_\u0062ytes":7}`,
161		}
162		for name, body := range valid {
163			t.Run(name, func(t *testing.T) {
164				st := newCaptureStore()
165				router := newCaptureRouter(st)
166	
167				direct, err := input.ParseRegistration(strings.NewReader(body))
168				if err != nil {
169					t.Fatalf("direct ParseRegistration: %v", err)
170				}
171				recorder := postArtifact(t, router, body)
172				if recorder.Code != http.StatusCreated {
173					t.Fatalf("HTTP status = %d, want 201 (%s)", recorder.Code, recorder.Body)
174				}
175				if st.regCalls != 1 {
176					t.Fatalf("store Register calls = %d, want exactly 1", st.regCalls)
177				}
178				recordMatchesInput(t, st.lastRecord, direct)
179	
180				// The identical retry keeps 201, reaches storage with the very
181				// same parsed input, and changes neither record nor tag target.
182				retry := postArtifact(t, router, body)
183				if retry.Code != http.StatusCreated {
184					t.Fatalf("retry status = %d, want 201 (%s)", retry.Code, retry.Body)
185				}
186				recordMatchesInput(t, st.lastRecord, direct)
187				if len(st.records) != 1 {
188					t.Fatalf("identical retry wrote a record: now %d", len(st.records))
189				}
190			})
191		}
192	
193		invalid := map[string]string{
194			"malformed json":      `{"repository":`,
195			"json array":          `["repository"]`,
196			"json null":           `null`,
197			"trailing content":    valid["plain"] + ` {}`,
198			"missing field":       registrationWithField("size_bytes", ""),
199			"null field":          registrationWithField("signature_verified", "null"),
200			"blank after trim":    registrationWithField("tag", `"  "`),
201			"duplicate last null": `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":4,"size_bytes":null}`,
202			"fractional integer":  `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1.5}`,
203			"exponential integer": `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":3e1,"size_bytes":1}`,
204			"string integer":      `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":"30","size_bytes":1}`,
205			"int64 overflow": `{"repository":"registry-demo/cap","digest":"` + testDigestA +
206				`","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":9223372036854775808}`,
207			"retention out of range": registration("registry-demo/cap", testDigestA, "t", true, 3651, 1),
208		}
209		for name, body := range invalid {
210			t.Run(name, func(t *testing.T) {
211				st := newCaptureStore()
212				router := newCaptureRouter(st)
213	
214				direct, err := input.ParseRegistration(strings.NewReader(body))
215				if !errors.Is(err, input.ErrInvalidInput) {
216					t.Fatalf("direct error = %v, want ErrInvalidInput", err)
217				}
218				if direct != (service.RegisterInput{}) {
219					t.Fatalf("direct result = %+v, want zero", direct)
220				}
221				assertErrorResponse(t, postArtifact(t, router, body),
222					http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
223				if st.regCalls != 0 {
224					t.Fatalf("rejected body reached storage %d times", st.regCalls)
225				}
226			})
227		}
228	}
229	
230	// TestDirectAndHTTPRegistrationReadFailure pins the reader-failure row on
231	// both entries with the same failing stream.
232	func TestDirectAndHTTPRegistrationReadFailure(t *testing.T) {
233		newFail := func() io.Reader {
234			return &registrationFailReader{prefix: []byte(`{"repository":"x"`), err: errors.New("read boom")}
235		}
236		st := newCaptureStore()
237		router := newCaptureRouter(st)
238	
239		direct, err := input.ParseRegistration(newFail())
240		if !errors.Is(err, input.ErrInvalidInput) || direct != (service.RegisterInput{}) {
241			t.Fatalf("direct read failure = (%+v, %v)", direct, err)
242		}
243	
244		recorder := httptest.NewRecorder()
245		request := httptest.NewRequest(http.MethodPost, "/v1/artifacts", newFail())
246		router.ServeHTTP(recorder, request)
247		assertErrorResponse(t, recorder, http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
248		if st.regCalls != 0 {
249			t.Fatalf("failed read reached storage %d times", st.regCalls)
250		}
251	}
252	
253	// registrationFailReader delivers prefix once, then err on every Read.
254	type registrationFailReader struct {
255		prefix []byte
256		err    error
257	}
258	
259	func (r *registrationFailReader) Read(p []byte) (int, error) {
260		if len(r.prefix) > 0 {
261			n := copy(p, r.prefix)
262			r.prefix = r.prefix[n:]
263			return n, nil
264		}
265		return 0, r.err
266	}
267	
268	// TestDirectAndHTTPQueryShareOneEntry drives each query shape through both
269	// entries: the dispatched store call reconstructs exactly the service.Query
270	// the direct call returned; invalid rows are the sentinel plus 400 with no
271	// storage call.
272	func TestDirectAndHTTPQueryShareOneEntry(t *testing.T) {
273		st := newCaptureStore()
274		router := newCaptureRouter(st)
275		const repo = "registry-demo/qcap"
276		// Seed so every legal selector resolves: alpha, beta, a space tag and a
277		// plus tag.
278		mustRegister(t, router, repo, testDigestA, "alpha")
279		mustRegister(t, router, repo, testDigestB, "beta")
280		postArtifact(t, router, registration(repo, testDigestD, "a b", true, regRetention, regSizeA))
281		postArtifact(t, router, registration(repo, testDigestE, "a+b", true, regRetention, regSizeA))
282	
283		cases := map[string]string{
284			"repository list":           "repository=" + repo,
285			"repository padded":         "repository=++" + repo + "++",
286			"tag first value":           "repository=" + repo + "&tag=alpha&tag=beta",
287			"tag later illegal ignored": "repository=" + repo + "&tag=alpha&tag=",
288			"tag later missing ignored": "repository=" + repo + "&tag=beta&tag=missing",
289			"digest first value":        "repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB,
290			"digest later malformed":    "repository=" + repo + "&digest=" + testDigestA + "&digest=sha256:xyz",
291			"plus decodes to space":     "repository=" + repo + "&tag=a+b",
292			"percent-20 decodes space":  "repository=" + repo + "&tag=a%20b",
293			"percent-2B decodes plus":   "repository=" + repo + "&tag=a%2Bb",
294			"escaped tag name":          "repository=" + repo + "&%74ag=alpha",
295			"cased name is unknown":     "repository=" + repo + "&Tag=alpha",
296			"unknown repeats ignored":   "repository=" + repo + "&tag=alpha&frob=1&frob=2",
297			"undecodable pair skipped":  "repository=" + repo + "&tag=%zz",
298			"bad pair before good tag":  "repository=" + repo + "&tag=%zz&tag=alpha",
299			"semicolon segment skipped": "repository=" + repo + "&tag=alpha;evil=1",
300			"selector after semicolon":  "repository=" + repo + "&digest=" + testDigestA + ";x=1&tag=alpha",
301		}
302		for name, raw := range cases {
303			t.Run(name, func(t *testing.T) {
304				direct, err := input.ParseQuery(raw)
305				if err != nil {
306					t.Fatalf("direct ParseQuery(%q): %v", raw, err)
307				}
308				recorder := getArtifacts(t, router, raw)
309				if recorder.Code == http.StatusBadRequest {
310					t.Fatalf("HTTP 400 for a query direct parsing accepted: %s", recorder.Body)
311				}
312				if !reflect.DeepEqual(st.lastQuery, direct) {
313					t.Fatalf("dispatched query = %+v, want direct result %+v", st.lastQuery, direct)
314				}
315			})
316		}
317	
318		// A literal %3B in a tag value reaches storage decoded (no segment is
319		// skipped); it simply matches no tag, which is the 404 path.
320		raw := "repository=" + repo + "&tag=a%3Bb"
321		direct, err := input.ParseQuery(raw)
322		if err != nil {
323			t.Fatalf("direct %%3B query: %v", err)
324		}
325		if direct.Tag != "a;b" {
326			t.Fatalf("%%3B tag = %q, want a;b", direct.Tag)
327		}
328		assertErrorResponse(t, getArtifacts(t, router, raw), http.StatusNotFound, codeNotFound, msgNotFound)
329		if !reflect.DeepEqual(st.lastQuery, direct) {
330			t.Fatalf("%%3B dispatched query = %+v, want %+v", st.lastQuery, direct)
331		}
332	
333		invalid := []string{
334			"",
335			"repository=&tag=alpha",
336			"repository=%20%20",
337			"repository&tag=alpha",
338			"repository=" + repo + "&tag=",
339			"repository=" + repo + "&tag=%20%20",
340			"repository=" + repo + "&digest=sha256:xyz",
341			"repository=" + repo + "&digest=" + testDigestA + "+",
342			"repository=" + repo + "&tag=alpha&digest=" + testDigestA,
343			"repository=" + repo + "&digest=" + testDigestA + "&tag=alpha",
344			"?repository=" + repo,
345		}
346		for _, raw := range invalid {
347			t.Run("invalid/"+raw, func(t *testing.T) {
348				before := st.readCalls
349				direct, err := input.ParseQuery(raw)
350				if !errors.Is(err, input.ErrInvalidInput) || direct != (service.Query{}) {
351					t.Fatalf("direct ParseQuery(%q) = (%+v, %v), want zero + ErrInvalidInput", raw, direct, err)
352				}
353				assertErrorResponse(t, getArtifacts(t, router, raw),
354					http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
355				if st.readCalls != before {
356					t.Fatalf("invalid query %q reached storage", raw)
357				}
358			})
359		}
360	}
361	
362	// TestSharedEntryErrorPriorityOverStorageFailure proves on the real wiring
363	// that validation happens wholly inside the store-free input entry: with
364	// the store faulted, every invalid row keeps its 400 and never calls the
365	// store, while legal rows degrade to 503.
366	func TestSharedEntryErrorPriorityOverStorageFailure(t *testing.T) {
367		st := newCaptureStore()
368		router := newCaptureRouter(st)
369		body := registration("registry-demo/prio", testDigestA, "release", true, regRetention, regSizeA)
370		if recorder := postArtifact(t, router, body); recorder.Code != http.StatusCreated {
371			t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
372		}
373		st.fault = errors.New("capture backend down")
374	
375		// Invalid registration and query rows: 400, and the store counters do
376		// not move, even though every store method is faulted.
377		regBefore := st.regCalls
378		assertErrorResponse(t, postArtifact(t, router, registrationWithField("size_bytes", "null")),
379			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
380		assertErrorResponse(t, postArtifact(t, router, `{"repository":`),
381			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
382		assertErrorResponse(t, getArtifacts(t, router, "repository=registry-demo/prio&tag="),
383			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
384		assertErrorResponse(t, getArtifacts(t, router, "repository=x&tag=r&digest="+testDigestA),
385			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
386		if st.regCalls != regBefore {
387			t.Fatalf("invalid registration reached a faulted store: %d calls", st.regCalls-regBefore)
388		}
389	
390		// Direct parsing of the same rows rejects without any store existing in
391		// its call path — the input package simply cannot reach one.
392		if _, err := input.ParseRegistration(strings.NewReader(registrationWithField("size_bytes", "null"))); !errors.Is(err, input.ErrInvalidInput) {
393			t.Fatalf("direct invalid registration error = %v", err)
394		}
395		if _, err := input.ParseQuery("repository=x&tag=r&digest=" + testDigestA); !errors.Is(err, input.ErrInvalidInput) {
396			t.Fatalf("direct invalid query error = %v", err)
397		}
398	
399		// Legal rows pass the shared entry and reach the faulted store: 503.
400		assertErrorResponse(t, postArtifact(t, router,
401			registration("registry-demo/prio", testDigestB, "release", true, regRetention, regSizeB)),
402			http.StatusServiceUnavailable, codeStorage, msgStorage)
403		assertErrorResponse(t, getArtifacts(t, router, "repository=registry-demo/prio"),
404			http.StatusServiceUnavailable, codeStorage, msgStorage)
405	}
406	
407	// TestSharedEntryConflictIsServiceLayerNotParse shows parsing a body that
408	// conflicts with committed state still succeeds directly with a non-zero
409	// input; the 409 is the service's decision after parsing.
410	func TestSharedEntryConflictIsServiceLayerNotParse(t *testing.T) {
411		st := newCaptureStore()
412		router := newCaptureRouter(st)
413		first := registration("registry-demo/conf", testDigestA, "release", true, regRetention, regSizeA)
414		if recorder := postArtifact(t, router, first); recorder.Code != http.StatusCreated {
415			t.Fatalf("seed status = %d (%s)", recorder.Code, recorder.Body)
416		}
417	
418		changed := registration("registry-demo/conf", testDigestA, "moved", true, regRetention, regSizeB)
419		direct, err := input.ParseRegistration(strings.NewReader(changed))
420		if err != nil {
421			t.Fatalf("direct parse of a conflicting body rejected at the input boundary: %v", err)
422		}
423		if direct.Tag != "moved" || direct.SizeBytes != regSizeB {
424			t.Fatalf("direct parsed input = %+v", direct)
425		}
426		assertErrorResponse(t, postArtifact(t, router, changed),
427			http.StatusConflict, codeConflict, msgConflict)
428	}
