27		testDigestD = "sha256:" + "dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd"
28		testDigestE = "sha256:" + "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"
