31	// mustRegister posts one registration and fails the test on anything but 201.
32	func mustRegister(t *testing.T, router *gin.Engine, repo, digest, tag string) {
33		t.Helper()
34		recorder := postArtifact(t, router, registration(repo, digest, tag, true, regRetention, regSizeA))
35		if recorder.Code != http.StatusCreated {
36			t.Fatalf("register %s/%s/%s status = %d, want %d (%s)", repo, digest, tag,
37				recorder.Code, http.StatusCreated, recorder.Body)
