41	// TestRepeatedQueryParameterFirstValueWins pins the first-occurrence rule for
42	// every recognized parameter: repository, tag and digest. Values appearing
43	// later are never consulted, so they can neither retarget a hit nor rescue a
44	// first value that names a missing repository, tag or digest.
45	func TestRepeatedQueryParameterFirstValueWins(t *testing.T) {
46		router, _ := newTestRouter(t)
47		const repo = "registry-demo/qfirst"
48		mustRegister(t, router, repo, testDigestA, "alpha")
49		mustRegister(t, router, repo, testDigestB, "beta")
50	
51		hitCases := map[string]struct {
52			query      string
53			wantDigest string
54		}{
55			"tag alpha before beta": {"repository=" + repo + "&tag=alpha&tag=beta", testDigestA},
56			"tag beta before alpha": {"repository=" + repo + "&tag=beta&tag=alpha", testDigestB},
57			"tag third occurrence":  {"repository=" + repo + "&tag=alpha&tag=beta&tag=missing", testDigestA},
58			"digest A before B":     {"repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB, testDigestA},
59			"digest B before A":     {"repository=" + repo + "&digest=" + testDigestB + "&digest=" + testDigestA, testDigestB},
60			"digest third occurrence": {"repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB +
61				"&digest=" + testDigestC, testDigestA},
62		}
63		for name, tc := range hitCases {
64			t.Run(name, func(t *testing.T) {
65				record := soleRecord(t, getArtifacts(t, router, tc.query))
66				if record["digest"] != tc.wantDigest {
67					t.Fatalf("target digest = %v, want %s", record["digest"], tc.wantDigest)
68				}
69			})
70		}
71	
72		// The first repository value scopes the whole query even when a later value
73		// names a real repository.
74		first := getArtifacts(t, router, "repository="+repo+"&repository=registry-demo/other&tag=alpha")
75		if first.Code != http.StatusOK {
76			t.Fatalf("real repository first status = %d, want %d (%s)", first.Code, http.StatusOK, first.Body)
77		}
78		if got := soleRecord(t, first)["repository"]; got != repo {
79			t.Fatalf("later repository value retargeted the query to %v", got)
80		}
81	
82		// Mirrored: a first value naming a missing repository is a 404; the later
83		// value that names the seeded repository cannot rescue it.
84		assertErrorResponse(t,
85			getArtifacts(t, router, "repository=registry-demo/other&repository="+repo+"&tag=alpha"),
86			http.StatusNotFound, codeNotFound, msgNotFound)
87	}
