89	// TestRepeatedQueryParameterInvalidFirstValue pins both halves of the rule
90	// around validation: an illegal first value is the same 400 when legal values
91	// follow it, and a legal first value stays the query target when illegal or
92	// merely different values follow it. A later value can neither rescue nor
93	// override the first occurrence.
94	func TestRepeatedQueryParameterInvalidFirstValue(t *testing.T) {
95		router, _ := newTestRouter(t)
96		const repo = "registry-demo/qinvalid"
97		mustRegister(t, router, repo, testDigestA, "release")
98		mustRegister(t, router, repo, testDigestB, "release") // tag release now points at B
99	
100		// Illegal first occurrence: every later legal occurrence is ignored, so the
101		// request is the same 400 as a single illegal parameter.
102		invalid := map[string]string{
103			"repository empty first": "repository=&repository=" + repo + "&tag=release",
104			"repository blank first": "repository=%20%20&repository=" + repo + "&tag=release",
105			"repository bare first":  "repository&repository=" + repo + "&tag=release",
106			"tag empty first":        "repository=" + repo + "&tag=&tag=release",
107			"tag blank first":        "repository=" + repo + "&tag=%20%20&tag=release",
108			"tag bare first":         "repository=" + repo + "&tag&tag=release",
109			"digest bad first":       "repository=" + repo + "&digest=sha256:xyz&digest=" + testDigestA,
110			"digest bare first":      "repository=" + repo + "&digest&digest=" + testDigestA,
111			"digest spaced first":    "repository=" + repo + "&digest=+" + testDigestA + "&digest=" + testDigestA,
112		}
113		for name, query := range invalid {
114			t.Run(name, func(t *testing.T) {
115				assertErrorResponse(t, getArtifacts(t, router, query),
116					http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
117			})
118		}
119	
120		// Legal first occurrence keeps deciding the target. A later illegal value
121		// does not turn the query into a 400, and a later legal value that would
122		// hit elsewhere neither retargets nor rescues a first-value miss.
123		firstWins := map[string]struct {
124			query      string
125			wantStatus int
126			wantDigest string
127		}{
128			"repository legal then blank": {
129				"repository=" + repo + "&repository=%20&tag=release", http.StatusOK, testDigestB},
130			"tag legal then empty": {
131				"repository=" + repo + "&tag=release&tag=", http.StatusOK, testDigestB},
132			"tag legal then blank": {
133				"repository=" + repo + "&tag=release&tag=%20%20", http.StatusOK, testDigestB},
134			"tag legal then malformed digest-style value": {
135				"repository=" + repo + "&tag=release&tag=sha256:xyz", http.StatusOK, testDigestB},
136			"tag first misses then hits": {
137				"repository=" + repo + "&tag=missing&tag=release", http.StatusNotFound, ""},
138			"digest legal then malformed": {
139				"repository=" + repo + "&digest=" + testDigestA + "&digest=sha256:xyz", http.StatusOK, testDigestA},
140			"digest hits then other legal digest": {
141				"repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB, http.StatusOK, testDigestA},
142			"digest first misses then hits": {
143				"repository=" + repo + "&digest=" + testDigestC + "&digest=" + testDigestA, http.StatusNotFound, ""},
144		}
145		for name, tc := range firstWins {
146			t.Run(name, func(t *testing.T) {
147				recorder := getArtifacts(t, router, tc.query)
148				if tc.wantStatus == http.StatusNotFound {
149					assertErrorResponse(t, recorder, http.StatusNotFound, codeNotFound, msgNotFound)
150					return
151				}
152				if recorder.Code != http.StatusOK {
153					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
154				}
155				if got := soleRecord(t, recorder)["digest"]; got != tc.wantDigest {
156					t.Fatalf("target digest = %v, want %s", got, tc.wantDigest)
157				}
158			})
159		}
160	}
