162	// TestPercentDecodedParameterNamesAndCaseSensitivity proves that parameter
163	// matching happens on the percent-decoded name ('%74ag' is 'tag') while
164	// matching stays byte-for-byte case sensitive ('Tag' is an unknown parameter):
165	// unknown parameters, repeated or not, are ignored and never satisfy a
166	// required one.
167	func TestPercentDecodedParameterNamesAndCaseSensitivity(t *testing.T) {
168		router, _ := newTestRouter(t)
169		const repo = "registry-demo/qnames"
170		mustRegister(t, router, repo, testDigestA, "release") // tag release -> A
171		mustRegister(t, router, repo, testDigestB, "other")   // two records total
172	
173		// Escaped spellings of the known names decode to the same parameter, so the
174		// escaped and plain spellings collide and document order still picks the
175		// first value. %72='r', %74='t', %64='d'.
176		collisions := map[string]struct {
177			query      string
178			wantStatus int
179			wantDigest string
180		}{
181			"escaped repository first hits": {
182				"%72epository=" + repo + "&repository=registry-demo/other&tag=release", http.StatusOK, testDigestA},
183			"plain repository first misses": {
184				"repository=registry-demo/other&%72epository=" + repo + "&tag=release", http.StatusNotFound, ""},
185			"escaped tag first misses": {
186				"repository=" + repo + "&%74ag=missing&tag=release", http.StatusNotFound, ""},
187			"plain tag first hits": {
188				"repository=" + repo + "&tag=release&%74ag=missing", http.StatusOK, testDigestA},
189			"escaped tag alone is the tag query": {
190				"repository=" + repo + "&%74ag=release", http.StatusOK, testDigestA},
191			"escaped digest alone is the digest query": {
192				"repository=" + repo + "&%64igest=" + testDigestB, http.StatusOK, testDigestB},
193		}
194		for name, tc := range collisions {
195			t.Run(name, func(t *testing.T) {
196				recorder := getArtifacts(t, router, tc.query)
197				if tc.wantStatus == http.StatusNotFound {
198					assertErrorResponse(t, recorder, http.StatusNotFound, codeNotFound, msgNotFound)
199					return
200				}
201				if recorder.Code != http.StatusOK {
202					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
203				}
204				if got := soleRecord(t, recorder)["digest"]; got != tc.wantDigest {
205					t.Fatalf("target digest = %v, want %s", got, tc.wantDigest)
206				}
207			})
208		}
209	
210		// Case-sensitive names: a differently cased spelling is unknown, not the
211		// known parameter. With tag absent the request legally dispatches as the
212		// repository list (both records), which distinguishes ignoring from a tag
213		// query (one record).
214		uppercaseTag := getArtifacts(t, router, "repository="+repo+"&Tag=release")
215		if uppercaseTag.Code != http.StatusOK {
216			t.Fatalf("Tag= status = %d, want %d (%s)", uppercaseTag.Code, http.StatusOK, uppercaseTag.Body)
217		}
218		if records := allRecords(t, uppercaseTag); len(records) != 2 {
219			t.Fatalf("Tag= was treated as the tag query: got %d records, want the 2-record list", len(records))
220		}
221	
222		// A cased repository spelling cannot satisfy the required repository.
223		assertErrorResponse(t, getArtifacts(t, router, "Repository="+repo+"&tag=release"),
224			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
225	
226		// Case variants arriving after the known name are just unknown repeats.
227		one := soleRecord(t, getArtifacts(t, router, "repository="+repo+"&tag=release&TAG=other"))
228		if one["digest"] != testDigestA {
229			t.Fatalf("TAG= retargeted the tag query: %v", one)
230		}
231		one = soleRecord(t, getArtifacts(t, router, "repository="+repo+"&digest="+testDigestA+"&DIGEST="+testDigestB))
232		if one["digest"] != testDigestA {
233			t.Fatalf("DIGEST= retargeted the digest query: %v", one)
234		}
235	
236		// Unknown parameters, even repeated, are ignored and never block the query.
237		unknown := getArtifacts(t, router, "repository="+repo+"&tag=release&unknown=1&unknown=2&frob=")
238		if unknown.Code != http.StatusOK {
239			t.Fatalf("unknown parameters status = %d, want %d (%s)", unknown.Code, http.StatusOK, unknown.Body)
240		}
241		if records := allRecords(t, unknown); len(records) != 1 {
242			t.Fatalf("unknown parameters changed the query shape: %v", records)
243		}
244	}
245	
246	// TestPlusVersusPercent2BTagDecoding proves the query decoder is not
247	// field-specific: QueryUnescape turns '+' into a space but '%2B' into a literal
248	// plus sign, so the tags "a b" and "a+b" are different records. It also pins
249	// the per-field normalization boundary: repository/tag are trimmed after
250	// decoding while digest is matched by the anchored regex untrimmed.
251	func TestPlusVersusPercent2BTagDecoding(t *testing.T) {
252		router, _ := newTestRouter(t)
253		const repo = "registry-demo/qplus"
254		mustRegister(t, router, repo, testDigestA, "a b") // tag with a literal space
255		mustRegister(t, router, repo, testDigestB, "a+b") // tag with a literal plus
256		mustRegister(t, router, repo, testDigestC, "latest")
257	
258		// '+' and '%20' both decode to a space: both reach the space-tagged record.
259		for _, value := range []string{"a+b", "a%20b"} {
260			recorder := getArtifacts(t, router, "repository="+repo+"&tag="+value)
261			if recorder.Code != http.StatusOK {
262				t.Fatalf("tag %q status = %d, want %d (%s)", value, recorder.Code, http.StatusOK, recorder.Body)
263			}
264			if got := soleRecord(t, recorder)["digest"]; got != testDigestA {
265				t.Fatalf("tag %q resolved to %v, want space-tagged %s", value, got, testDigestA)
266			}
267		}
268	
269		// '%2B' decodes to a literal plus sign: a different tag and record.
270		plus := getArtifacts(t, router, "repository="+repo+"&tag=a%2Bb")
271		if plus.Code != http.StatusOK {
272			t.Fatalf("tag a%%2Bb status = %d, want %d (%s)", plus.Code, http.StatusOK, plus.Body)
273		}
274		if got := soleRecord(t, plus)["digest"]; got != testDigestB {
275			t.Fatalf("tag a%%2Bb resolved to %v, want plus-tagged %s", got, testDigestB)
276		}
277	
278		// TrimSpace runs after decoding: '+' edges become spaces and are trimmed,
279		// but '%2B' edges stay literal plus signs, which are not whitespace.
280		trimmed := getArtifacts(t, router, "repository="+repo+"&tag=+latest+")
281		if trimmed.Code != http.StatusOK {
282			t.Fatalf("tag +latest+ status = %d, want %d (%s)", trimmed.Code, http.StatusOK, trimmed.Body)
283		}
284		if got := soleRecord(t, trimmed)["digest"]; got != testDigestC {
285			t.Fatalf("+latest+ resolved to %v, want trimmed latest %s", got, testDigestC)
286		}
287		assertErrorResponse(t, getArtifacts(t, router, "repository="+repo+"&tag=%2Blatest%2B"),
288			http.StatusNotFound, codeNotFound, msgNotFound)
289	
290		// Repository gets the same decode-then-trim treatment: '+' padding becomes
291		// spaces and is trimmed away.
292		list := getArtifacts(t, router, "repository=++"+repo+"++")
293		if list.Code != http.StatusOK {
294			t.Fatalf("padded repository status = %d, want %d (%s)", list.Code, http.StatusOK, list.Body)
295		}
296		if digests := recordDigests(allRecords(t, list)); len(digests) != 3 ||
297			digests[0] != testDigestA || digests[1] != testDigestB || digests[2] != testDigestC {
298			t.Fatalf("list order = %v, want [A B C] in registration order", digests)
299		}
300	
301		// Digest is never trimmed: an encoded space before or after the value keeps
302		// it outside the anchored digest format, so the answer is 400 (not 404 and
303		// not a hit after trimming).
304		for _, value := range []string{"+" + testDigestA, testDigestA + "+", "%20" + testDigestA} {
305			assertErrorResponse(t, getArtifacts(t, router, "repository="+repo+"&digest="+value),
306				http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
307		}
308	}
309	
310	// TestParameterArrangementSelectsTargetAndQueriesAreReadOnly walks two records
311	// of different digests in one repository to show how parameter presence and
312	// order select the target — ordered list, current tag pointer, immutable
313	// digest record, and the 400 when both selectors are present — and then proves
314	// that queries never rewrite records, push times or tag pointers.
315	func TestParameterArrangementSelectsTargetAndQueriesAreReadOnly(t *testing.T) {
316		router, _ := newTestRouter(t)
317		const repo = "registry-demo/qarrange"
318	
319		first := postArtifact(t, router, registration(repo, testDigestA, "release", true, regRetention, regSizeA))
320		if first.Code != http.StatusCreated {
321			t.Fatalf("register A status = %d (%s)", first.Code, first.Body)
322		}
323		pushedA := decodeBody(t, first)["pushed_at"].(string)
324		second := postArtifact(t, router, registration(repo, testDigestB, "release", true, regRetention, regSizeB))
325		if second.Code != http.StatusCreated {
326			t.Fatalf("register B status = %d (%s)", second.Code, second.Body)
327		}
328		pushedB := decodeBody(t, second)["pushed_at"].(string)
329	
330		// Repository list: both records, in first-registration order.
331		if digests := recordDigests(allRecords(t, queryList(t, router, repo))); len(digests) != 2 ||
332			digests[0] != testDigestA || digests[1] != testDigestB {
333			t.Fatalf("list = %v, want [A B] in registration order", digests)
334		}
335	
336		// Tag follows the current pointer (B); digest returns the immutable
337		// original record A, push time and all, even though the tag moved.
338		if tagged := soleRecord(t, queryByTag(t, router, repo, "release")); tagged["digest"] != testDigestB ||
339			tagged["pushed_at"] != pushedB {
340			t.Fatalf("tag release = %v, want current pointer B/%s", tagged, pushedB)
341		}
342		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, repo, testDigestA)),
343			repo, testDigestA, "release", true, float64(regRetention), float64(regSizeA), pushedA)
344	
345		// Tag and digest together never degrade into a list or a single-condition
346		// query, in either parameter order.
347		assertErrorResponse(t,
348			getArtifacts(t, router, "repository="+repo+"&tag=release&digest="+testDigestB),
349			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
350		assertErrorResponse(t,
351			getArtifacts(t, router, "repository="+repo+"&digest="+testDigestB+"&tag=release"),
352			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
353	
354		// snapshot captures every successful view of committed state.
355		snapshot := func() string {
356			views := []string{
357				queryList(t, router, repo).Body.String(),
358				queryByTag(t, router, repo, "release").Body.String(),
359				queryByDigest(t, router, repo, testDigestA).Body.String(),
360				queryByDigest(t, router, repo, testDigestB).Body.String(),
361			}
362			return strings.Join(views, "\n")
363		}
364		before := snapshot()
365	
366		// A barrage of reads: hits, first-value misses, rejected shapes and
367		// differently decoded tags — none of which may write anything.
368		barrage := []string{
369			"repository=" + repo + "&tag=release&tag=missing",
370			"repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB,
371			"repository=" + repo + "&tag=release&digest=" + testDigestB,
372			"repository=" + repo + "&digest=" + testDigestC,
373			"repository=" + repo + "&tag=a%2Bb",
374			"repository=" + repo + "&tag=+release+",
375			"repository=registry-demo/other",
376			"repository=" + repo,
377		}
378		for _, query := range barrage {
379			getArtifacts(t, router, query)
380		}
381	
382		if after := snapshot(); after != before {
383			t.Fatalf("committed state changed through queries:\nbefore: %s\nafter:  %s", before, after)
384		}
385		// Explicit re-check of the pointer and the original record after the reads.
386		if tagged := soleRecord(t, queryByTag(t, router, repo, "release")); tagged["digest"] != testDigestB ||
387			tagged["pushed_at"] != pushedB {
388			t.Fatalf("tag pointer changed after queries: %v", tagged)
389		}
390		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, repo, testDigestA)),
391			repo, testDigestA, "release", true, float64(regRetention), float64(regSizeA), pushedA)
392	}
393	
394	// TestInvalidQueryFirstValueWinsOverStorageFailure closes the underlying
395	// SQLite file and checks the ordering on the query entry: an illegal first
396	// occurrence keeps its 400 before any storage access, while legal queries
397	// degrade to 503 storage_unavailable.
398	func TestInvalidQueryFirstValueWinsOverStorageFailure(t *testing.T) {
399		path := filepath.Join(t.TempDir(), "service.db")
400		st, err := store.Open(path)
401		if err != nil {
402			t.Fatalf("open: %v", err)
403		}
404		router := NewRouter(st)
405		const repo = "registry-demo/qdown"
406		mustRegister(t, router, repo, testDigestA, "release")
407		mustRegister(t, router, repo, testDigestB, "release")
408		if err := st.Close(); err != nil {
409			t.Fatalf("close store: %v", err)
410		}
411	
412		// Illegal first occurrences keep their 400 even though the store is down.
413		invalid := []string{
414			"repository=&repository=" + repo + "&tag=release",
415			"repository=" + repo + "&tag=&tag=release",
416			"repository=" + repo + "&tag=%20%20&tag=release",
417			"repository=" + repo + "&digest=sha256:xyz&digest=" + testDigestA,
418			"repository=" + repo + "&digest&digest=" + testDigestA,
419		}
420		for _, query := range invalid {
421			assertErrorResponse(t, getArtifacts(t, router, query),
422				http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
423		}
424	
425		// Legal queries keep the published 503 degradation.
426		assertErrorResponse(t, queryList(t, router, repo),
427			http.StatusServiceUnavailable, codeStorage, msgStorage)
428		assertErrorResponse(t, queryByTag(t, router, repo, "release"),
429			http.StatusServiceUnavailable, codeStorage, msgStorage)
430		assertErrorResponse(t, queryByDigest(t, router, repo, testDigestA),
431			http.StatusServiceUnavailable, codeStorage, msgStorage)
432	}
433	
434	// TestQueryInputRulesOnAssemblyEntry proves the query input boundary lives in
435	// the shared handler chain, not in the SQLite assembly: on
436	// NewRouterWithStore with a caller-supplied store, repeated parameters still
437	// take their first value, an illegal first value still wins its 400,
438	// percent-decoded names still collide, case variants and unknown parameters
439	// are still ignored, '+' and '%2B' still reach different tags, and /healthz
440	// is untouched by any of it.
441	func TestQueryInputRulesOnAssemblyEntry(t *testing.T) {
442		st := newAssemblyStore()
443		router := newAssemblyRouter(st, &assemblyProbe{})
444		const repo = "registry-demo/qasm"
445		mustRegister(t, router, repo, testDigestA, "alpha")
446		mustRegister(t, router, repo, testDigestB, "beta")
447		mustRegister(t, router, repo, testDigestD, "a b")
448		mustRegister(t, router, repo, testDigestE, "a+b")
449	
450		// First occurrence wins for every recognized parameter.
451		firstWins := map[string]struct {
452			query      string
453			wantStatus int
454			wantDigest string
455		}{
456			"tag alpha first":          {"repository=" + repo + "&tag=alpha&tag=beta", http.StatusOK, testDigestA},
457			"tag beta first":           {"repository=" + repo + "&tag=beta&tag=alpha", http.StatusOK, testDigestB},
458			"digest A first":           {"repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB, http.StatusOK, testDigestA},
459			"digest B first":           {"repository=" + repo + "&digest=" + testDigestB + "&digest=" + testDigestA, http.StatusOK, testDigestB},
460			"repository first missing": {"repository=registry-demo/other&repository=" + repo + "&tag=alpha", http.StatusNotFound, ""},
461			"escaped tag first misses": {"repository=" + repo + "&%74ag=missing&tag=alpha", http.StatusNotFound, ""},
462			"plain tag first hits":     {"repository=" + repo + "&tag=alpha&%74ag=missing", http.StatusOK, testDigestA},
463			"plus reaches space tag":   {"repository=" + repo + "&tag=a+b", http.StatusOK, testDigestD},
464			"percent-2B reaches plus":  {"repository=" + repo + "&tag=a%2Bb", http.StatusOK, testDigestE},
465		}
466		for name, tc := range firstWins {
467			t.Run(name, func(t *testing.T) {
468				recorder := getArtifacts(t, router, tc.query)
469				if tc.wantStatus == http.StatusNotFound {
470					assertErrorResponse(t, recorder, http.StatusNotFound, codeNotFound, msgNotFound)
471					return
472				}
473				if recorder.Code != http.StatusOK {
474					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
475				}
476				if got := soleRecord(t, recorder)["digest"]; got != tc.wantDigest {
477					t.Fatalf("target digest = %v, want %s", got, tc.wantDigest)
478				}
479			})
480		}
481	
482		// Illegal first value: later legal values cannot rescue it.
483		for _, query := range []string{
484			"repository=&repository=" + repo + "&tag=alpha",
485			"repository=" + repo + "&tag=&tag=alpha",
486			"repository=" + repo + "&digest=sha256:xyz&digest=" + testDigestA,
487		} {
488			assertErrorResponse(t, getArtifacts(t, router, query),
489				http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
490		}
491	
492		// Legal first value cannot be overridden by a later illegal one.
493		if recorder := getArtifacts(t, router,
494			"repository="+repo+"&digest="+testDigestA+"&digest=sha256:xyz"); recorder.Code != http.StatusOK {
495			t.Fatalf("legal first digest status = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
496		}
497	
498		// A cased name is unknown: Tag= leaves the repository list, while tag and
499		// digest together stay a 400; unknown repeats are ignored.
500		if records := allRecords(t, getArtifacts(t, router, "repository="+repo+"&Tag=alpha")); len(records) != 4 {
501			t.Fatalf("Tag= was treated as the tag query: got %d records, want the 4-record list", len(records))
502		}
503		assertErrorResponse(t,
504			getArtifacts(t, router, "repository="+repo+"&tag=alpha&digest="+testDigestA),
505			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
506		if recorder := getArtifacts(t, router,
507			"repository="+repo+"&tag=alpha&frob=1&frob=2"); recorder.Code != http.StatusOK {
508			t.Fatalf("unknown repeats status = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
509		}
510	
511		// The health entry is untouched by the query input boundary.
512		if recorder := getHealth(t, router); recorder.Code != http.StatusOK {
513			t.Fatalf("/healthz = %d, want %d (%s)", recorder.Code, http.StatusOK, recorder.Body)
514		}
515	}
