49	func (a *assemblyStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
50		a.calls["register"]++
51		if a.fault != nil {
52			return service.Record{}, 0, a.fault
53		}
54		key := assemblyID(in.Repository, in.Digest)
55		if idx, ok := a.byID[key]; ok {
56			existing := a.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		a.byID[key] = len(a.records)
66		a.records = append(a.records, in)
67		if a.tags[in.Repository] == nil {
68			a.tags[in.Repository] = make(map[string]string)
69		}
70		a.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
