74	func (a *assemblyStore) ListRecords(repository string) ([]service.Record, error) {
75		a.calls["list"]++
76		if a.fault != nil {
77			return nil, a.fault
78		}
79		var out []service.Record
80		for _, record := range a.records {
81			if record.Repository == repository {
82				out = append(out, record)
83			}
84		}
85		return out, nil
86	}
